const $=id=>document.getElementById(id);const esc=v=>String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#039;');let user=null,targetId='',data=null,dirty=new Set();
function toast(msg){const t=$('toast');t.textContent=msg;t.classList.remove('hidden');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.add('hidden'),2200)}function half(h){return h==='first'?'상반기':'하반기'}function statusText(s){return s==='submitted'?'제출완료':s==='in_progress'?'작성중':s==='evaluating'?'채점중':s==='completed'?'평가완료':s==='published'?'결과공개':'작성전'}function hasSubmission(t){return Number(t?.has_submission_record||0)>0}function fmtBytes(n){n=Number(n||0);if(n<1024)return n+' B';if(n<1048576)return (n/1024).toFixed(1)+' KB';return (n/1048576).toFixed(1)+' MB'}
const api=(path,opt={})=>window.EHSApi.request(path,opt);
let modalFocusReturn=null;function setModalBackgroundPaused(paused){for(const el of [$('app'),$('ehsGlobalHeader')]){if(!el)continue;if(paused){el.inert=true;el.setAttribute('aria-hidden','true')}else{el.inert=false;el.removeAttribute('aria-hidden')}}document.documentElement.classList.toggle('modal-open',paused);document.body.classList.toggle('modal-open',paused)}function modal(title,body,actions=''){const panel=$('modal');if(panel.classList.contains('hidden'))modalFocusReturn=document.activeElement;$('modalTitle').textContent=title;$('modalBody').innerHTML=body;$('modalActions').innerHTML=actions;setModalBackgroundPaused(true);panel.classList.remove('hidden');queueMicrotask(()=>panel.querySelector('.modal-actions .primary,.modal-actions button,.modal-close')?.focus({preventScroll:true}))}function closeModal(){const panel=$('modal');if(panel.classList.contains('hidden'))return;panel.classList.add('hidden');setModalBackgroundPaused(false);document.dispatchEvent(new CustomEvent('ehs:modal-closed'));const focus=modalFocusReturn;modalFocusReturn=null;if(focus?.isConnected)queueMicrotask(()=>focus.focus({preventScroll:true}))}$('modalClose').onclick=closeModal;$('modal').onclick=e=>{if(e.target===$('modal'))closeModal()};document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('modal').classList.contains('hidden'))closeModal()});
function itemPrepared(i){return Number(i.applicable)===0||String(i.description||'').trim()||(i.files||[]).length}function grouped(){const map=new Map();for(const i of data.workspace.items||[]){const key=i.parent_category_name||i.category_name||'기타';if(!map.has(key))map.set(key,[]);map.get(key).push(i)}return [...map.entries()]}
function renderNav(){return grouped().map(([cat,items])=>`<div class="nav-cat">${esc(cat)}</div>${items.map(i=>`<button class="nav-item" type="button" data-nav="${esc(i.target_item_state_id)}"><span class="nav-name">${esc((i.item_code?i.item_code+' ':'')+i.item_name)}</span><span class="nav-state ${Number(i.applicable)===0?'na':itemPrepared(i)?'done':''}">${Number(i.applicable)===0?'N/A':itemPrepared(i)?'완료':'미작성'}</span></button>`).join('')}`).join('')}
function evidenceHtml(i){const cap=data.capabilities||{};return `<div class="evidence"><div class="evidence-head"><strong>증빙자료</strong><span class="upload-note">PDF · JPG · PNG · Excel · HWP · PowerPoint · Word · 최대 25MB</span></div>${cap.evidence_upload?`<div class="upload-row"><label class="file-pick" for="file-${esc(i.target_item_state_id)}">+ 파일 첨부</label><input class="file-input" id="file-${esc(i.target_item_state_id)}" data-file-input="${esc(i.target_item_state_id)}" type="file" accept=".pdf,.jpg,.jpeg,.png,.xls,.xlsx,.hwp,.hwpx,.ppt,.pptx,.doc,.docx"></div>`:`<div class="na-copy">증빙파일 저장소가 아직 연결되지 않아 파일 첨부는 현재 사용할 수 없습니다. 설명 입력과 제출은 정상적으로 사용할 수 있습니다.</div>`}<div class="file-list">${(i.files||[]).map(f=>`<div class="file-row"><span class="file-name">${esc(f.file_name)}</span><span class="file-size">${fmtBytes(f.file_size)}</span><span><button class="file-action preview" type="button" data-preview-file="${esc(f.id)}" data-file-name="${esc(f.file_name)}" data-file-size="${Number(f.file_size||0)}" data-content-type="${esc(f.content_type||'')}">미리보기</button><button class="file-action" type="button" data-download="${esc(f.id)}">다운로드</button><button class="file-action delete" type="button" data-delete-file="${esc(f.id)}">삭제</button></span></div>`).join('')}</div></div>`}
function itemCard(i){const na=Number(i.applicable)===0;return `<section class="item-card ${na?'na':''}" id="item-${esc(i.target_item_state_id)}"><div class="item-head"><div><div class="item-title-line"><span class="item-code">${esc(i.item_code||'')}</span><span class="item-title">${esc(i.item_name)}</span><span class="score-badge ${i.item_type==='bonus'?'bonus':''}">${i.item_type==='bonus'?'가점 +':'배점 '}${Number(i.max_score||0)}점</span>${na?'<span class="score-badge na-badge">N/A</span>':''}</div><div class="item-category">${esc([i.parent_category_name,i.category_name].filter(Boolean).join(' · '))}</div></div>${i.guide_text||i.judgment_guide?`<button class="guide-btn" type="button" data-guide-toggle="${esc(i.target_item_state_id)}">i</button>`:''}</div><div class="item-body">${i.guide_text||i.judgment_guide?`<div class="guide-panel" data-guide-panel="${esc(i.target_item_state_id)}">${i.guide_text?`[제출가이드]\n${esc(i.guide_text)}`:''}${i.guide_text&&i.judgment_guide?'\n\n':''}${i.judgment_guide?`[판정기준]\n${esc(i.judgment_guide)}`:''}</div>`:''}${na?`<div class="na-copy">이 항목은 현재 회사의 업종·상시근로자 기준에 따라 N/A 처리되었습니다.${i.manual_na_reason?`<br>사유: ${esc(i.manual_na_reason)}`:''}</div>`:`<div class="input-label-row"><label for="desc-${esc(i.target_item_state_id)}">제출 설명</label><span>필요한 내용만 간결하게 입력하세요.</span></div><div class="field"><textarea id="desc-${esc(i.target_item_state_id)}" data-desc="${esc(i.target_item_state_id)}" placeholder="예: 최근 실시일, 대상 인원, 조치 결과 등 평가자가 확인해야 할 내용을 입력하세요.">${esc(i.description||'')}</textarea></div>${evidenceHtml(i)}<div class="item-actions"><span class="save-state" id="state-${esc(i.target_item_state_id)}">${i.description?'저장된 내용':'미작성'}</span><button class="btn" type="button" data-save-item="${esc(i.target_item_state_id)}">저장</button></div>`}</div></section>`}
function render(){const w=data.workspace,t=w.target,s=w.summary,submitted=hasSubmission(t),displayStatus=!submitted&&t.status==='submitted'?'in_progress':t.status;const editable=data.capabilities?.editable!==false;$('app').innerHTML=`<div class="hero"><div><div class="eyebrow">i-PaSS · ${t.year}년 ${half(t.half)} 이행수준평가</div><h1>${esc(t.company_name)} 평가자료 제출</h1><div class="hero-meta"><span class="chip ${displayStatus==='submitted'?'green':'orange'}">${statusText(displayStatus)}</span><span class="chip gray">${esc(t.start_at||'-')} ~ ${esc(t.end_at||'-')}</span>${t.industry_name?`<span class="chip gray">${esc(t.industry_name)}</span>`:''}</div></div><div class="hero-actions"><button class="btn" id="refreshBtn" type="button">새로고침</button><button class="btn primary" id="topSubmitBtn" type="button">평가자료 제출</button></div></div><div class="summary"><div class="metric progress"><span>작성률</span><b>${s.progress}%</b></div><div class="metric"><span>전체 항목</span><b>${s.total}</b></div><div class="metric"><span>N/A</span><b>${s.na}</b></div><div class="metric ${s.blank?'warn':''}"><span>미작성 항목</span><b>${s.blank}</b></div></div><div class="progressbar"><span style="width:${s.progress}%"></span></div><div class="layout"><aside class="sidebar"><div class="sidebar-head"><strong>평가항목</strong><span>항목을 선택하면 해당 작성 위치로 이동합니다.</span></div><div class="nav-list">${renderNav()}</div></aside><div class="content"><section class="profile-card"><div class="card-head"><strong>회사 기본정보</strong><span id="profileState">${t.business_number&&t.representative_name&&t.worker_count!=null?'저장됨':'필수 입력'}</span></div><div class="profile-body"><div class="profile-grid"><div class="field"><label>사업자등록번호</label><input id="businessNumber" value="${esc(t.business_number||'')}" placeholder="000-00-00000"></div><div class="field"><label>대표자명</label><input id="representativeName" value="${esc(t.representative_name||'')}"></div><div class="field"><label>상시근로자 수</label><input id="workerCount" type="number" min="0" value="${t.worker_count??''}"></div></div><div class="profile-actions"><button class="btn" id="saveProfileBtn" type="button">기본정보 저장</button></div></div></section>${(w.items||[]).map(itemCard).join('')}<section class="submit-card"><div><h3>${editable?'작성한 평가자료를 제출하세요.':'현재는 평가자료를 수정할 수 없습니다.'}</h3><p>${editable?'미작성 항목이 있어도 제출할 수 있습니다. 자료가 없는 항목은 평가 시 감점될 수 있으며, 평가기간 내에는 제출 후에도 수정할 수 있습니다.':t.status==='published'?'관리자가 결과를 공개하여 제출자료가 확정되었습니다.':'평가자료 수정기간이 종료되었습니다.'}</p><div class="status">${submitted&&t.submitted_at?`최초 제출: ${esc(String(t.submitted_at).replace('T',' ').slice(0,16))}`:'아직 제출하지 않았습니다.'}</div></div><button class="btn primary" id="bottomSubmitBtn" type="button">평가자료 제출</button></section></div></div><div class="sticky-submit"><button class="btn primary" id="mobileSubmitBtn" type="button">평가자료 제출</button></div>`;bind();if(!editable){document.querySelectorAll('input,textarea,button[data-save-item],#saveProfileBtn,#topSubmitBtn,#bottomSubmitBtn,#mobileSubmitBtn,[data-file-input],[data-delete-file]').forEach(el=>el.disabled=true);document.querySelectorAll('.file-pick').forEach(el=>el.classList.add('disabled'))}}
function bind(){document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{const el=$('item-'+b.dataset.nav);if(el){el.scrollIntoView({behavior:'smooth',block:'start'});document.querySelectorAll('.nav-item').forEach(x=>x.classList.remove('active'));b.classList.add('active')}});document.querySelectorAll('[data-guide-toggle]').forEach(b=>b.onclick=()=>document.querySelector(`[data-guide-panel="${CSS.escape(b.dataset.guideToggle)}"]`)?.classList.toggle('open'));document.querySelectorAll('[data-desc]').forEach(t=>t.oninput=()=>dirty.add(t.dataset.desc));document.querySelectorAll('[data-save-item]').forEach(b=>b.onclick=()=>saveItem(b.dataset.saveItem));document.querySelectorAll('[data-file-input]').forEach(i=>i.onchange=()=>uploadFile(i.dataset.fileInput,i));document.querySelectorAll('[data-download]').forEach(b=>b.onclick=()=>downloadFile(b.dataset.download));document.querySelectorAll('[data-delete-file]').forEach(b=>b.onclick=()=>deleteFile(b.dataset.deleteFile));$('saveProfileBtn').onclick=saveProfile;$('refreshBtn').onclick=()=>load(true);['topSubmitBtn','bottomSubmitBtn','mobileSubmitBtn'].forEach(id=>$(id).onclick=submitEvaluation)}
async function saveProfile(){const btn=$('saveProfileBtn'),state=$('profileState');btn.disabled=true;state.textContent='저장 중...';try{const d=await api(`/api/partner/submission/${encodeURIComponent(targetId)}/profile`,{method:'PATCH',body:JSON.stringify({business_number:$('businessNumber').value,representative_name:$('representativeName').value,worker_count:$('workerCount').value})});data.workspace=d.workspace;toast('기본정보를 저장했습니다.');render()}catch(e){state.textContent=e.message;state.className='error-text'}finally{if(document.body.contains(btn))btn.disabled=false}}
async function saveItem(id){const state=$('state-'+id),btn=document.querySelector(`[data-save-item="${CSS.escape(id)}"]`),desc=$('desc-'+id);if(!desc)return;btn.disabled=true;state.textContent='저장 중...';try{await api(`/api/partner/submission/${encodeURIComponent(targetId)}/items/${encodeURIComponent(id)}`,{method:'PATCH',body:JSON.stringify({description:desc.value})});const item=data.workspace.items.find(x=>x.target_item_state_id===id);if(item)item.description=desc.value;dirty.delete(id);state.textContent='✓ 저장됨';state.className='save-state ok';toast('저장했습니다.')}catch(e){state.textContent=e.message;state.className='save-state error-text'}finally{btn.disabled=false}}
async function uploadFile(id,input){const file=input.files?.[0];if(!file)return;const fd=new FormData();fd.append('file',file);toast('파일 업로드 중...');try{await api(`/api/partner/submission/${encodeURIComponent(targetId)}/items/${encodeURIComponent(id)}/files`,{method:'POST',body:fd});toast('파일을 첨부했습니다.');await load(true)}catch(e){modal('파일 첨부 실패',esc(e.message),'<button class="btn" id="modalOk">확인</button>');setTimeout(()=>{$('modalOk').onclick=closeModal},0)}finally{input.value=''}}
function downloadFile(id){return window.EHSApi.download(`/api/partner/submission/files/${encodeURIComponent(id)}`,'증빙자료')}
async function deleteFile(id){if(!confirm('첨부파일을 삭제할까요?'))return;try{await api(`/api/partner/submission/files/${encodeURIComponent(id)}`,{method:'DELETE'});toast('삭제했습니다.');await load(true)}catch(e){alert(e.message)}}
async function saveDirty(){for(const id of [...dirty])await saveItem(id)}
async function submitEvaluation(){try{if(dirty.size){await saveDirty()}const s=data.workspace.summary;modal('평가자료 제출 확인',`현재 작성률은 <b>${s.progress}%</b>이며 미작성 항목은 <b>${s.blank}개</b>입니다.<br><br>자료가 없는 항목은 그대로 제출할 수 있으며 평가 시 감점될 수 있습니다. 제출하시겠습니까?`,`<button class="btn" id="cancelSubmit">취소</button><button class="btn primary" id="confirmSubmit">제출</button>`);$('cancelSubmit').onclick=closeModal;$('confirmSubmit').onclick=async()=>{const b=$('confirmSubmit');b.disabled=true;b.textContent='제출 중...';try{await api(`/api/partner/submission/${encodeURIComponent(targetId)}/submit`,{method:'POST'});closeModal();toast('평가자료를 제출했습니다.');await load(true)}catch(e){b.disabled=false;b.textContent='다시 시도';alert(e.message)}}}catch(e){alert(e.message)}}
async function load(force=false){$('app').innerHTML='<div class="loading" aria-label="평가자료 화면 준비"></div>';try{const d=await api(`/api/partner/submission/${encodeURIComponent(targetId)}`);if(d.user?.role&&d.user.role!=='partner')throw new Error('협력사 계정에서만 이용할 수 있습니다.');data=d;user=d.user||user;window.__EHS_PAGE_USER=user;document.dispatchEvent(new CustomEvent('ehs:user-ready',{detail:user}));dirty.clear();$('userLabel').textContent=[user?.company_name,user?.name].filter(Boolean).join(' · ');render()}catch(e){$('app').innerHTML=`<div class="loading error-text">${esc(e.message)}</div>`}}
function goHome(){if(dirty.size&&!confirm('저장하지 않은 변경사항이 있습니다. 이동할까요?'))return;location.href='/home'}$('homeBtn').onclick=goHome;$('brandBtn').onclick=goHome;window.addEventListener('beforeunload',e=>{if(dirty.size){e.preventDefault();e.returnValue=''}});
(async function boot(){try{targetId=new URLSearchParams(location.search).get('target')||'';if(!targetId)throw new Error('평가 대상 정보가 없습니다.');if(!window.EHSAuth.readSession()){window.EHSAuth.redirectToLogin(location.pathname+location.search);return}await load()}catch(e){if(e?.status===401)return;$('app').innerHTML=`<div class="loading error-text">${esc(window.EHSApi.describe(e))}</div>`}})();
